/**
 * Durable per-session PagerDuty channel state, persisted with the turn so
 * stream-event handlers can address the incident without re-parsing the
 * webhook.
 */
export function emptyPagerDutyChannelState(overrides = {}) {
    return {
        incidentId: null,
        incidentNumber: null,
        incidentKey: null,
        serviceId: null,
        eventType: null,
        eventId: null,
        deliveryId: null,
        occurredAt: null,
        ...overrides,
    };
}
export function pagerDutyChannelStateForEvent(input) {
    return emptyPagerDutyChannelState({
        incidentId: input.incidentId ?? null,
        incidentNumber: input.incidentNumber ?? null,
        incidentKey: input.incidentKey ?? null,
        serviceId: input.serviceId ?? null,
        eventType: input.eventType,
        eventId: input.eventId,
        deliveryId: input.deliveryId ?? null,
        occurredAt: input.occurredAt ?? null,
    });
}
